<?php include 'includes/header.php'; require_admin(); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=$_POST['name']; $username=$_POST['username']; $role=$_POST['role']; $pass=password_hash($_POST['password']?:'admin123', PASSWORD_DEFAULT); $stmt=$conn->prepare('INSERT INTO users(name,username,password,role) VALUES(?,?,?,?)'); $stmt->bind_param('ssss',$name,$username,$pass,$role); $msg=$stmt->execute()?'User created.':'Username already exists.'; }
$res=$conn->query('SELECT id,name,username,role,created_at FROM users ORDER BY id DESC'); ?>
<h3>User Management</h3><?php if($msg):?><div class='alert alert-info'><?=$msg?></div><?php endif;?><div class='row g-3'><div class='col-md-4'><div class='card cardx p-3'><form method='post'><input class='form-control mb-2' name='name' placeholder='Name' required><input class='form-control mb-2' name='username' placeholder='Username' required><input class='form-control mb-2' name='password' placeholder='Password'><select class='form-select mb-2' name='role'><option value='staff'>Staff</option><option value='viewer'>Viewer</option><option value='admin'>Admin</option></select><button class='btn btn-primary'>Add User</button></form></div></div><div class='col-md-8'><div class='card cardx p-3'><table class='table datatable'><thead><tr><th>ID</th><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr></thead><tbody><?php while($u=$res->fetch_assoc()):?><tr><td><?=$u['id']?></td><td><?=e($u['name'])?></td><td><?=e($u['username'])?></td><td><?=e($u['role'])?></td><td><?=$u['created_at']?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include 'includes/footer.php'; ?>
